-- Analytical target schema. Separate from runtime D1 aggregate tables.
-- Not evidence that every source entity has been acquired/populated.
PRAGMA foreign_keys=ON;
CREATE TABLE data_sources(source_id TEXT PRIMARY KEY,provider TEXT NOT NULL,url TEXT NOT NULL,license TEXT NOT NULL,redistribution_status TEXT NOT NULL CHECK(redistribution_status IN('permitted','restricted','unverified')),verified_at TEXT NOT NULL);
CREATE TABLE source_documents(document_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources,url TEXT NOT NULL,published_at TEXT,retrieved_at TEXT NOT NULL,sha256 TEXT NOT NULL CHECK(length(sha256)=64),availability_status TEXT NOT NULL CHECK(availability_status IN('verified','approximate','unknown')));
CREATE TABLE dataset_versions(dataset_version TEXT PRIMARY KEY,created_at TEXT NOT NULL,manifest_sha256 TEXT NOT NULL,pipeline_version TEXT NOT NULL,validation_status TEXT NOT NULL CHECK(validation_status IN('pending','passed','failed','limited')));
CREATE TABLE data_quality_issues(issue_id TEXT PRIMARY KEY,dataset_version TEXT NOT NULL REFERENCES dataset_versions,entity_type TEXT NOT NULL,entity_id TEXT,field_name TEXT,severity TEXT NOT NULL CHECK(severity IN('info','warning','error')),description TEXT NOT NULL,resolution TEXT);
CREATE TABLE fact_provenance(fact_id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,field_name TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES source_documents,dataset_version TEXT NOT NULL REFERENCES dataset_versions,transformation TEXT NOT NULL,value_kind TEXT NOT NULL CHECK(value_kind IN('historical_fact','transformed_observation','derived_statistic','model_estimate','simulation','assumption','unavailable')));
CREATE TABLE teams(team_id TEXT PRIMARY KEY,canonical_label TEXT NOT NULL);
CREATE TABLE team_identities(identity_id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams,city TEXT NOT NULL,nickname TEXT NOT NULL,abbreviation TEXT NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT,CHECK(valid_to IS NULL OR valid_to>valid_from),UNIQUE(team_id,valid_from));
CREATE TABLE seasons(season INTEGER PRIMARY KEY,starts_at TEXT NOT NULL,completed_at TEXT,regular_season_games INTEGER NOT NULL CHECK(regular_season_games BETWEEN 1 AND 20),playoff_teams INTEGER NOT NULL CHECK(playoff_teams IN(12,14)));
CREATE TABLE team_seasons(team_id TEXT NOT NULL REFERENCES teams,season INTEGER NOT NULL REFERENCES seasons,identity_id TEXT NOT NULL REFERENCES team_identities,conference TEXT NOT NULL,division TEXT NOT NULL,PRIMARY KEY(team_id,season));
CREATE TABLE players(player_id TEXT PRIMARY KEY,full_name TEXT NOT NULL,birth_date TEXT);
CREATE TABLE player_identifiers(namespace TEXT NOT NULL,external_id TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES players,match_method TEXT NOT NULL CHECK(match_method IN('exact','audited_manual')),PRIMARY KEY(namespace,external_id));
CREATE TABLE colleges(college_id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE college_player_seasons(player_id TEXT NOT NULL REFERENCES players,college_id TEXT NOT NULL REFERENCES colleges,season INTEGER NOT NULL,position TEXT NOT NULL,conference TEXT,PRIMARY KEY(player_id,college_id,season));
CREATE TABLE college_statistics(player_id TEXT NOT NULL,college_id TEXT NOT NULL,season INTEGER NOT NULL,statistic TEXT NOT NULL,value REAL,unit TEXT NOT NULL,missing_reason TEXT,available_at TEXT,document_id TEXT NOT NULL REFERENCES source_documents,PRIMARY KEY(player_id,college_id,season,statistic),FOREIGN KEY(player_id,college_id,season) REFERENCES college_player_seasons,CHECK((value IS NOT NULL AND missing_reason IS NULL) OR(value IS NULL AND missing_reason IN('unknown','not_applicable','not_measured','not_reported','source_unavailable','failed_ingestion','incomplete_season'))));
CREATE TABLE draft_classes(draft_year INTEGER PRIMARY KEY,draft_starts_at TEXT NOT NULL,information_cutoff TEXT NOT NULL,dataset_version TEXT NOT NULL REFERENCES dataset_versions,CHECK(information_cutoff<=draft_starts_at));
CREATE TABLE prospects(prospect_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players,draft_year INTEGER NOT NULL REFERENCES draft_classes,college_id TEXT REFERENCES colleges,position TEXT NOT NULL,eligible_at TEXT,eligibility_evidence TEXT NOT NULL,playable INTEGER NOT NULL CHECK(playable IN(0,1)),UNIQUE(player_id,draft_year));
CREATE TABLE historical_draft_picks(pick_id TEXT PRIMARY KEY,draft_year INTEGER NOT NULL REFERENCES draft_classes,round INTEGER NOT NULL CHECK(round BETWEEN 1 AND 7),overall INTEGER,original_team_id TEXT NOT NULL REFERENCES teams,selecting_team_id TEXT REFERENCES teams,prospect_id TEXT UNIQUE REFERENCES prospects,compensatory INTEGER NOT NULL CHECK(compensatory IN(0,1)),forfeited INTEGER NOT NULL CHECK(forfeited IN(0,1)),executed_at TEXT,UNIQUE(draft_year,overall),CHECK(overall IS NOT NULL OR forfeited=1));
CREATE TABLE draft_pick_ownership(pick_id TEXT NOT NULL REFERENCES historical_draft_picks,valid_from TEXT NOT NULL,valid_to TEXT,owner_team_id TEXT NOT NULL REFERENCES teams,document_id TEXT NOT NULL REFERENCES source_documents,PRIMARY KEY(pick_id,valid_from),CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE TABLE historical_trades(trade_id TEXT PRIMARY KEY,effective_at TEXT NOT NULL,announced_at TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE trade_assets(trade_id TEXT NOT NULL REFERENCES historical_trades,asset_index INTEGER NOT NULL,from_team_id TEXT NOT NULL REFERENCES teams,to_team_id TEXT NOT NULL REFERENCES teams,asset_type TEXT NOT NULL CHECK(asset_type IN('pick','player','conditional_pick')),pick_id TEXT REFERENCES historical_draft_picks,player_id TEXT REFERENCES players,condition_text TEXT,PRIMARY KEY(trade_id,asset_index),CHECK(from_team_id<>to_team_id),CHECK((asset_type='player' AND player_id IS NOT NULL AND pick_id IS NULL) OR(asset_type='pick' AND pick_id IS NOT NULL AND player_id IS NULL) OR(asset_type='conditional_pick' AND condition_text IS NOT NULL AND player_id IS NULL)));
CREATE TABLE combine_results(prospect_id TEXT NOT NULL REFERENCES prospects,measurement TEXT NOT NULL,value REAL,unit TEXT NOT NULL,missing_reason TEXT,measured_at TEXT,available_at TEXT,document_id TEXT NOT NULL REFERENCES source_documents,PRIMARY KEY(prospect_id,measurement),CHECK((value IS NOT NULL AND missing_reason IS NULL) OR(value IS NULL AND missing_reason IN('unknown','not_applicable','not_measured','not_reported','source_unavailable','failed_ingestion'))));
CREATE TABLE injury_events(injury_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players,event_at TEXT,available_at TEXT NOT NULL,description TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE scouting_reports(report_id TEXT PRIMARY KEY,prospect_id TEXT NOT NULL REFERENCES prospects,published_at TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES source_documents,permitted_excerpt TEXT,license_notes TEXT NOT NULL);
CREATE TABLE roster_memberships(roster_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players,team_id TEXT NOT NULL REFERENCES teams,valid_from TEXT NOT NULL,valid_to TEXT,roster_status TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES source_documents,CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE TABLE contracts(contract_id TEXT PRIMARY KEY,player_id TEXT NOT NULL REFERENCES players,team_id TEXT NOT NULL REFERENCES teams,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,announced_at TEXT NOT NULL,cap_charge_usd REAL CHECK(cap_charge_usd>=0),document_id TEXT NOT NULL REFERENCES source_documents,CHECK(ends_at>starts_at));
CREATE TABLE coaching_staff(appointment_id TEXT PRIMARY KEY,team_id TEXT NOT NULL REFERENCES teams,person_name TEXT NOT NULL,role TEXT NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT,document_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE historical_games(game_id TEXT PRIMARY KEY,season INTEGER NOT NULL REFERENCES seasons,week INTEGER NOT NULL,game_type TEXT NOT NULL CHECK(game_type IN('REG','WC','DIV','CON','SB')),starts_at TEXT NOT NULL,home_team_id TEXT NOT NULL REFERENCES teams,away_team_id TEXT NOT NULL REFERENCES teams,home_score INTEGER CHECK(home_score>=0),away_score INTEGER CHECK(away_score>=0),document_id TEXT NOT NULL REFERENCES source_documents,CHECK(home_team_id<>away_team_id),CHECK((home_score IS NULL)=(away_score IS NULL)));
CREATE TABLE historical_player_seasons(player_id TEXT NOT NULL REFERENCES players,season INTEGER NOT NULL REFERENCES seasons,games_played INTEGER,games_started INTEGER,metric_name TEXT NOT NULL,metric_value REAL,label_available_at TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES source_documents,PRIMARY KEY(player_id,season,metric_name),CHECK(games_played>=0),CHECK(games_started>=0 AND games_started<=games_played));
CREATE TABLE historical_team_seasons(team_id TEXT NOT NULL REFERENCES teams,season INTEGER NOT NULL REFERENCES seasons,wins INTEGER NOT NULL CHECK(wins>=0),losses INTEGER NOT NULL CHECK(losses>=0),ties INTEGER NOT NULL CHECK(ties>=0),points_for INTEGER NOT NULL CHECK(points_for>=0),points_against INTEGER NOT NULL CHECK(points_against>=0),document_id TEXT NOT NULL REFERENCES source_documents,PRIMARY KEY(team_id,season));
CREATE TABLE feature_definitions(feature_name TEXT NOT NULL,feature_version TEXT NOT NULL,description TEXT NOT NULL,unit TEXT NOT NULL,derivation TEXT NOT NULL,PRIMARY KEY(feature_name,feature_version));
CREATE TABLE feature_values(prospect_id TEXT NOT NULL REFERENCES prospects,feature_name TEXT NOT NULL,feature_version TEXT NOT NULL,dataset_version TEXT NOT NULL REFERENCES dataset_versions,value REAL,missing_reason TEXT,effective_at TEXT NOT NULL,available_at TEXT NOT NULL,permitted_cutoff TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES source_documents,PRIMARY KEY(prospect_id,feature_name,feature_version,dataset_version),FOREIGN KEY(feature_name,feature_version) REFERENCES feature_definitions,CHECK(available_at<=permitted_cutoff),CHECK(effective_at<=permitted_cutoff),CHECK((value IS NOT NULL AND missing_reason IS NULL) OR(value IS NULL AND missing_reason IS NOT NULL)));
CREATE TABLE model_versions(model_version TEXT PRIMARY KEY,dataset_version TEXT NOT NULL REFERENCES dataset_versions,training_cutoff TEXT NOT NULL,training_label_max_available_at TEXT NOT NULL,artifact_sha256 TEXT NOT NULL,methodology TEXT NOT NULL,CHECK(training_label_max_available_at<=training_cutoff));
CREATE TABLE model_predictions(prediction_id TEXT PRIMARY KEY,model_version TEXT NOT NULL REFERENCES model_versions,prospect_id TEXT NOT NULL REFERENCES prospects,cutoff TEXT NOT NULL,target TEXT NOT NULL,estimate REAL NOT NULL,lower_bound REAL,upper_bound REAL,CHECK(lower_bound IS NULL OR lower_bound<=estimate),CHECK(upper_bound IS NULL OR upper_bound>=estimate));
CREATE TABLE users(user_id TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE disclosure_policies(disclosure_version TEXT PRIMARY KEY,mode TEXT NOT NULL CHECK(mode IN('historical','daily')),field_rules_json TEXT NOT NULL,finalized_at TEXT NOT NULL);
CREATE TABLE daily_challenges(challenge_date TEXT PRIMARY KEY,scenario_json TEXT NOT NULL,dataset_version TEXT NOT NULL REFERENCES dataset_versions,model_version TEXT NOT NULL REFERENCES model_versions,engine_version TEXT NOT NULL,disclosure_version TEXT NOT NULL REFERENCES disclosure_policies,seed_commitment TEXT NOT NULL,scoring_version TEXT NOT NULL,ensemble_size INTEGER NOT NULL CHECK(ensemble_size>0),finalized_at TEXT NOT NULL);
CREATE TABLE game_runs(game_run_id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users,mode TEXT NOT NULL CHECK(mode IN('historical','daily')),draft_year INTEGER NOT NULL REFERENCES draft_classes,team_id TEXT NOT NULL REFERENCES teams,seed TEXT NOT NULL,dataset_version TEXT NOT NULL REFERENCES dataset_versions,model_version TEXT NOT NULL REFERENCES model_versions,engine_version TEXT NOT NULL,disclosure_version TEXT NOT NULL REFERENCES disclosure_policies,scenario_json TEXT NOT NULL,challenge_date TEXT REFERENCES daily_challenges,revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),state TEXT NOT NULL CHECK(state IN('drafting','draft_complete','simulating','complete','failed')),CHECK((mode='daily' AND challenge_date IS NOT NULL) OR(mode='historical' AND challenge_date IS NULL)));
CREATE TABLE game_pick_assets(game_run_id TEXT NOT NULL REFERENCES game_runs,pick_id TEXT NOT NULL REFERENCES historical_draft_picks,owner_team_id TEXT NOT NULL REFERENCES teams,PRIMARY KEY(game_run_id,pick_id));
CREATE TABLE game_draft_picks(game_run_id TEXT NOT NULL,pick_id TEXT NOT NULL,team_id TEXT NOT NULL REFERENCES teams,prospect_id TEXT NOT NULL REFERENCES prospects,selected_at TEXT NOT NULL,PRIMARY KEY(game_run_id,pick_id),UNIQUE(game_run_id,prospect_id),FOREIGN KEY(game_run_id,pick_id) REFERENCES game_pick_assets);
CREATE TABLE game_trades(trade_id TEXT PRIMARY KEY,game_run_id TEXT NOT NULL REFERENCES game_runs,from_team_id TEXT NOT NULL REFERENCES teams,to_team_id TEXT NOT NULL REFERENCES teams,transaction_revision INTEGER NOT NULL,accepted_at TEXT NOT NULL,CHECK(from_team_id<>to_team_id),UNIQUE(game_run_id,transaction_revision));
CREATE TABLE game_trade_assets(trade_id TEXT NOT NULL REFERENCES game_trades,game_run_id TEXT NOT NULL,pick_id TEXT NOT NULL,from_team_id TEXT NOT NULL REFERENCES teams,to_team_id TEXT NOT NULL REFERENCES teams,PRIMARY KEY(trade_id,pick_id),FOREIGN KEY(game_run_id,pick_id) REFERENCES game_pick_assets,CHECK(from_team_id<>to_team_id));
CREATE TABLE game_scouting_actions(action_id TEXT PRIMARY KEY,game_run_id TEXT NOT NULL REFERENCES game_runs,prospect_id TEXT NOT NULL REFERENCES prospects,resource_cost INTEGER NOT NULL CHECK(resource_cost>0),action_kind TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(game_run_id,prospect_id,action_kind));
CREATE TABLE game_saves(game_run_id TEXT NOT NULL REFERENCES game_runs,revision INTEGER NOT NULL,state_json TEXT NOT NULL,state_sha256 TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(game_run_id,revision));
-- Private server-side mapping: never return or expose this table to the client.
CREATE TABLE game_public_prospect_ids(game_run_id TEXT NOT NULL REFERENCES game_runs,public_id TEXT NOT NULL,prospect_id TEXT NOT NULL REFERENCES prospects,PRIMARY KEY(game_run_id,public_id),UNIQUE(game_run_id,prospect_id));
CREATE TABLE game_reveal_events(event_id TEXT PRIMARY KEY,game_run_id TEXT NOT NULL REFERENCES game_runs,prospect_id TEXT NOT NULL REFERENCES prospects,disclosure_version TEXT NOT NULL REFERENCES disclosure_policies,revealed_fields_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE simulation_runs(simulation_run_id TEXT PRIMARY KEY,game_run_id TEXT NOT NULL REFERENCES game_runs,branch TEXT NOT NULL CHECK(branch IN('baseline','alternate')),replicate INTEGER NOT NULL CHECK(replicate>=0),seed TEXT NOT NULL,model_version TEXT NOT NULL REFERENCES model_versions,dataset_version TEXT NOT NULL REFERENCES dataset_versions,configuration_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','running','complete','failed')),UNIQUE(game_run_id,branch,replicate));
CREATE TABLE simulation_games(simulation_run_id TEXT NOT NULL REFERENCES simulation_runs,game_id TEXT NOT NULL,season INTEGER NOT NULL,game_type TEXT NOT NULL,home_team_id TEXT NOT NULL REFERENCES teams,away_team_id TEXT NOT NULL REFERENCES teams,home_score INTEGER NOT NULL CHECK(home_score>=0),away_score INTEGER NOT NULL CHECK(away_score>=0),PRIMARY KEY(simulation_run_id,game_id),CHECK(home_team_id<>away_team_id));
CREATE TABLE simulation_player_seasons(simulation_run_id TEXT NOT NULL REFERENCES simulation_runs,player_id TEXT NOT NULL REFERENCES players,team_id TEXT NOT NULL REFERENCES teams,season INTEGER NOT NULL,metric_name TEXT NOT NULL,metric_value REAL NOT NULL,PRIMARY KEY(simulation_run_id,player_id,season,metric_name));
CREATE TABLE simulation_team_seasons(simulation_run_id TEXT NOT NULL REFERENCES simulation_runs,team_id TEXT NOT NULL REFERENCES teams,season INTEGER NOT NULL,wins INTEGER NOT NULL CHECK(wins>=0),losses INTEGER NOT NULL CHECK(losses>=0),ties INTEGER NOT NULL CHECK(ties>=0),PRIMARY KEY(simulation_run_id,team_id,season));
CREATE TABLE historical_comparisons(game_run_id TEXT NOT NULL REFERENCES game_runs,metric_name TEXT NOT NULL,actual REAL,baseline REAL NOT NULL,alternate REAL NOT NULL,mean_paired_difference REAL NOT NULL,lower_difference REAL,upper_difference REAL,ensemble_count INTEGER NOT NULL CHECK(ensemble_count>0),PRIMARY KEY(game_run_id,metric_name));
CREATE TABLE daily_attempts(challenge_date TEXT NOT NULL REFERENCES daily_challenges,user_id TEXT NOT NULL REFERENCES users,game_run_id TEXT NOT NULL UNIQUE REFERENCES game_runs,submitted_at TEXT,PRIMARY KEY(challenge_date,user_id));
CREATE TABLE daily_leaderboard_entries(challenge_date TEXT NOT NULL,user_id TEXT NOT NULL,score REAL NOT NULL,score_components_json TEXT NOT NULL,scoring_version TEXT NOT NULL,result_sha256 TEXT NOT NULL,PRIMARY KEY(challenge_date,user_id),FOREIGN KEY(challenge_date,user_id) REFERENCES daily_attempts);
CREATE TRIGGER ownership_no_overlap BEFORE INSERT ON draft_pick_ownership WHEN EXISTS(SELECT 1 FROM draft_pick_ownership p WHERE p.pick_id=NEW.pick_id AND NEW.valid_from<coalesce(p.valid_to,'9999-12-31T23:59:59Z') AND p.valid_from<coalesce(NEW.valid_to,'9999-12-31T23:59:59Z')) BEGIN SELECT RAISE(ABORT,'overlapping ownership'); END;
CREATE TRIGGER ownership_no_overlap_update BEFORE UPDATE ON draft_pick_ownership WHEN EXISTS(SELECT 1 FROM draft_pick_ownership p WHERE p.pick_id=NEW.pick_id AND NOT(p.pick_id=OLD.pick_id AND p.valid_from=OLD.valid_from) AND NEW.valid_from<coalesce(p.valid_to,'9999-12-31T23:59:59Z') AND p.valid_from<coalesce(NEW.valid_to,'9999-12-31T23:59:59Z')) BEGIN SELECT RAISE(ABORT,'overlapping ownership'); END;
CREATE TRIGGER pick_owner BEFORE INSERT ON game_draft_picks WHEN NOT EXISTS(SELECT 1 FROM game_pick_assets a WHERE a.game_run_id=NEW.game_run_id AND a.pick_id=NEW.pick_id AND a.owner_team_id=NEW.team_id) BEGIN SELECT RAISE(ABORT,'wrong pick owner'); END;
CREATE TRIGGER pick_eligible BEFORE INSERT ON game_draft_picks WHEN NOT EXISTS(SELECT 1 FROM prospects p WHERE p.prospect_id=NEW.prospect_id AND p.playable=1) BEGIN SELECT RAISE(ABORT,'baseline-only prospect'); END;
CREATE TRIGGER selected_asset_locked BEFORE UPDATE OF owner_team_id ON game_pick_assets WHEN EXISTS(SELECT 1 FROM game_draft_picks p WHERE p.game_run_id=OLD.game_run_id AND p.pick_id=OLD.pick_id) BEGIN SELECT RAISE(ABORT,'selected pick locked'); END;
CREATE TRIGGER prediction_cutoff BEFORE INSERT ON model_predictions WHEN EXISTS(SELECT 1 FROM model_versions m WHERE m.model_version=NEW.model_version AND m.training_cutoff>NEW.cutoff) BEGIN SELECT RAISE(ABORT,'model trained after cutoff'); END;
CREATE TRIGGER sim_version_matches BEFORE INSERT ON simulation_runs WHEN NOT EXISTS(SELECT 1 FROM game_runs g WHERE g.game_run_id=NEW.game_run_id AND g.dataset_version=NEW.dataset_version AND g.model_version=NEW.model_version) BEGIN SELECT RAISE(ABORT,'simulation version mismatch'); END;
CREATE TRIGGER challenge_immutable BEFORE UPDATE ON daily_challenges BEGIN SELECT RAISE(ABORT,'immutable challenge'); END;
CREATE TRIGGER leaderboard_immutable BEFORE UPDATE ON daily_leaderboard_entries BEGIN SELECT RAISE(ABORT,'immutable result'); END;
CREATE TRIGGER disclosure_immutable BEFORE UPDATE ON disclosure_policies BEGIN SELECT RAISE(ABORT,'immutable disclosure policy'); END;
CREATE INDEX ix_prospects_class_position ON prospects(draft_year,position,playable);
CREATE INDEX ix_features_cutoff ON feature_values(permitted_cutoff,feature_name);
CREATE INDEX ix_rosters_team_time ON roster_memberships(team_id,valid_from,valid_to);
CREATE INDEX ix_games_season ON historical_games(season,game_type);
CREATE INDEX ix_game_user ON game_runs(user_id,state);
CREATE INDEX ix_leaderboard_score ON daily_leaderboard_entries(challenge_date,score DESC);
